 else try{$category=(string)($_POST['category']??'other');$file=$_FILES['document']??null;if(!isset($categoryLabels[$category])||!is_array($file))throw new RuntimeException('Choose a document category and a file.');if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new RuntimeException('The file upload did not complete. Select a smaller file and try again.');$size=(int)($file['size']??0);if($size<1||$size>10*1024*1024)throw new RuntimeException('Documents must be smaller than 10 MB.');$tmp=(string)($file['tmp_name']??'');if(!is_uploaded_file($tmp))throw new RuntimeException('The uploaded file could not be verified.');$finfo=new finfo(FILEINFO_MIME_TYPE);$mime=$finfo->file($tmp);$allowedTypes=['application/pdf'=>['pdf'],'image/jpeg'=>['jpg','jpeg'],'image/png'=>['png']];if(!isset($allowedTypes[$mime]))throw new RuntimeException('Only PDF, JPEG and PNG documents are accepted.');$original=basename(str_replace('\\','/',(string)($file['name']??'document')));$original=preg_replace('/[\x00-\x1F\x7F]/u','',$original)?:'document';$original=mb_substr($original,0,255);$extension=strtolower(pathinfo($original,PATHINFO_EXTENSION));if(!in_array($extension,$allowedTypes[$mime],true))throw new RuntimeException('The file extension does not match its content type.');if(!is_dir($privateDir)&&!mkdir($privateDir,0700,true)&&!is_dir($privateDir))throw new RuntimeException('Private document storage is unavailable.');$key=bin2hex(random_bytes(32));$destination=$privateDir.'/'.$key;if(!move_uploaded_file($tmp,$destination))throw new RuntimeException('The private file could not be saved.');chmod($destination,0600);$hash=hash_file('sha256',$destination);try{SchoolDatabase::transaction(function(PDO $pdo)use($studentId,$category,$original,$key,$mime,$size,$hash,$user):void{$q=$pdo->prepare('INSERT INTO school_student_documents (student_id,category,original_name,storage_key,mime_type,byte_size,sha256,uploaded_by) VALUES (:student,:category,:name,:key,:mime,:size,:hash,:user)');$q->execute(['student'=>$studentId,'category'=>$category,'name'=>$original,'key'=>$key,'mime'=>$mime,'size'=>$size,'hash'=>$hash,'user'=>(int)$user['id']]);$id=(int)$pdo->lastInsertId();(new AuditService())->record((int)$user['id'],'student.document.upload','school_student_documents',$id,['student_id'=>$studentId,'category'=>$category,'mime_type'=>$mime,'byte_size'=>$size]);});}catch(Throwable $exception){@unlink($destination);throw $exception;}$message='Private student document uploaded.';
